'use strict';
// CIS 425 is deliberately isolated from the CIS 320 data and saved progress.
const KEY425='cis425-midterm-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const shuffledOrder=a=>{const b=shuffle(a);if(b.length>1&&b.every((x,i)=>x===a[i]))b.push(b.shift());return b};
const paragraphs=s=>String(s||'').split(/\n+/).filter(Boolean).flatMap(p=>{const sentences=p.split(/(?<=[.!?])\s+(?=[A-Z])/),chunks=[];for(let i=0;i<sentences.length;i+=2)chunks.push(sentences.slice(i,i+2).join(' '));return chunks}).map(p=>`<p>${esc(p)}</p>`).join('');
let D,section=0,view='teach',session=null,lesson=null,storageOK=true;
let progress={cards:{},lessons:{},xp:0,days:[]};
try{const p=JSON.parse(localStorage.getItem(KEY425));if(p&&p.cards&&typeof p.cards==='object'&&!Array.isArray(p.cards)&&typeof p.xp==='number'&&Array.isArray(p.days))progress={...progress,...p,lessons:p.lessons||{}}}catch{storageOK=false}
function save(){try{localStorage.setItem(KEY425,JSON.stringify(progress))}catch{storageOK=false}stats()}
function stats(){$('#stats').innerHTML=`<span>✦ ${progress.xp} XP</span><span>${progress.days.length} study day${progress.days.length===1?'':'s'}</span>`;$('#storage-status').textContent=storageOK?'CIS 425 progress saves separately in this browser.':'Browser storage is unavailable. Progress will last only for this visit.'}
function record(x,ok){const old=progress.cards[x.id]||{seen:0,level:0};const level=ok?Math.min(6,old.level+1):0;progress.cards[x.id]={seen:old.seen+1,level,completed:old.completed||ok,due:Date.now()+(ok?[1,3,7,14,30,60][level-1]*86400000:60000)};progress.xp+=ok?10:2;const day=new Date().toLocaleDateString('en-CA');if(!progress.days.includes(day))progress.days.push(day);save()}
const filtered=items=>section?items.filter(x=>x.section===section):items;
const completed=x=>!!progress.cards[x.id]?.completed;
const sec=id=>D.sections.find(s=>s.id===id);
const source=x=>x.number?x:D.questions.find(q=>q.number===x.source);
const label=x=>`Midterm · ${sec(x.section).title}`;
function sources(x){const q=source(x);if(!q)return '';return `<details class="question-source"><summary>Sources and exam wording</summary>${q.sample?`<p><b>Professor sample: ${esc(q.sample)}</b></p>`:''}<p>${esc(q.q)}</p>${q.originalOptions?`<p>Original options: ${q.originalOptions.map(esc).join(' · ')}</p>`:''}${q.refs.map(([id,where])=>`<p class="source-note">${esc(D.sources.find(s=>s.id===id)?.name)} · ${esc(where)}</p>`).join('')}${q.uncertain?'<p class="notice">The supplied wording does not establish a dependable single answer. Read the qualification; this item is excluded from scored exams.</p>':''}<p class="tiny">Authored study explanation, not an instructor-issued answer key.</p></details>`}
function picker(){if(["beginner","samples","coverage","readings"].includes(view))return `<p class="tiny muted">Whole midterm</p>`;return `<label class="tiny">Midterm topic <select id="section"><option value="0">All topics</option>${D.sections.map(s=>`<option value="${s.id}" ${s.id===section?'selected':''}>${s.title}</option>`).join('')}</select></label>`}
function heading(t,p){return `<div class="heading"><div><div class="eyebrow">CIS 425 / DEFENSIVE CYBERSECURITY</div><h1>${esc(t)}</h1><p class="muted">${esc(p)}</p></div>${picker()}</div>`}
const navs=[['beginner','○','Start from zero'],['samples','☷','Professor examples'],['coverage','✓','Topic checklist'],['teach','☀','Learn First'],['practice','◈','Practice'],['flash','▤','Flashcards'],['map','▧','See the connections'],['exam','✓','Practice exam']];
const focused=[['apply','◎','Apply your knowledge'],['sort','≋','Sorting & sequences'],['abbrev','⌁','Abbreviations'],['math','#','RSA & hash lab'],['discussion','◇','Discussion practice']];
const reference=[['terms','Aa','Terms & definitions'],['guide','☷','Full answered guide'],['readings','↗','Sources & corrections']];
function buttonNav([id,icon,title]){return `<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon} &nbsp; ${title}</button>`}
function chrome(){stats();$('#nav').innerHTML=navs.map(buttonNav).join('')+`<details ${focused.some(x=>x[0]===view)?'open':''}><summary>Focused practice</summary>${focused.map(buttonNav).join('')}</details><details ${reference.some(x=>x[0]===view)?'open':''}><summary>Reference library</summary>${reference.map(buttonNav).join('')}</details>`;$('#modebar').innerHTML=`<button data-view="teach" class="${view==='teach'?'active':''}">Learn First</button><button data-view="practice" class="${view==='practice'?'active':''}">Practice Quiz</button><span class="tiny muted">CIS 425 · Midterm</span>`}
function navigate(v){$("#nav").setAttribute("data-menu-open","false");$("#study-menu").setAttribute("aria-expanded","false");view=v;session=null;lesson=null;render();window.scrollTo(0,0)}
function render(){chrome();const fn={beginner:beginnerHome,samples:samplesHome,coverage:coverageHome,teach:teachHome,practice:practiceHome,flash:flashHome,map:mapHome,exam:examHome,apply:applyHome,sort:sortHome,abbrev:abbrevHome,math:mathHome,discussion:discussionHome,terms:termsHome,guide:guideHome,readings:readingsHome}[view];fn();const p=$('#section');if(p)p.onchange=()=>{section=+p.value;render()}}
function teachHome(){const sections=section?D.sections.filter(s=>s.id===section):D.sections;$('#app').innerHTML=heading('Understand it before you memorize it.','Start with a plain explanation, see a concrete example, then practice. Study one concept at a time, then explain it in a scenario.')+`<div class="notice">Midterm focus: textbook Chapters 1 and 3, Lectures 1–8, and relevant lab and in-class work. All 21 professor examples are answered, with focused supporting lessons from direct review of all eight lecture decks and assigned textbook sections. October 15 notes emphasize business use and defenses rather than memorizing tool commands. New to security? Start from zero. Then use Professor examples and the Topic checklist to connect each source to practice.</div><div class="actions"><button data-view="beginner">Start from zero</button><button data-view="samples">All 21 professor examples</button><button data-view="coverage">Chapter & lecture checklist</button></div>`+sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(q=>progress.lessons[q.id]).length;return `<section class="card" style="margin-top:22px"><span class="tag">${esc(s.reading)}</span><h2>${s.id}. ${esc(s.title)}</h2><p>${esc(s.intro)}</p><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p class="tiny">${done} / ${qs.length} lessons completed</p><div class="lesson-list">${qs.map(q=>`<button data-lesson="${q.number}"><span class="badge">${q.number}</span><span class="lesson-label">${esc(q.title)}<small>${esc(q.q)}</small></span><span aria-label="${progress.lessons[q.id]?'Completed':'Not completed'}">${progress.lessons[q.id]?'✓':'→'}</span></button>`).join('')}</div></section>`}).join('')}
function learningSequence(){return D.sections.filter(s=>!section||s.id===section).flatMap(s=>D.questions.filter(q=>q.section===s.id))}
function nextLearningLesson(number){const list=learningSequence(),i=list.findIndex(q=>q.number===number);return i<0?null:list[i+1]}
function learningNextLabel(number){const next=nextLearningLesson(number);return next?'Next lesson → '+next.title:'Finish learning →'}
function continueLearning(number){const q=D.questions.find(q=>q.number===number);if(!q)return;progress.lessons[q.id]=true;save();const next=nextLearningLesson(number);if(next){openLesson(next.number);window.scrollTo(0,0);return}const list=learningSequence(),remaining=list.filter(q=>!progress.lessons[q.id]);session=null;view='teach';chrome();$('#app').innerHTML=`<section class="card study"><h1>${remaining.length?'You reached the last lesson':'All lessons complete ✓'}</h1><p>${list.length-remaining.length} / ${list.length} lessons completed${section?' in '+esc(sec(section).title):' in this class'}.</p><div class="bar"><span style="width:${100*(list.length-remaining.length)/list.length}%"></span></div><p>${remaining.length?'Some earlier lessons are still unread. Continue with the first unfinished lesson to complete this selection.':'You’ve worked through every lesson in this selection. You can practice or revisit any lesson whenever you want.'}</p><div class="actions">${remaining.length?`<button class="primary" data-lesson="${remaining[0].number}">Continue unfinished lessons →</button>`:'<button class="primary" data-view="practice">Practice what you learned</button>'}<button data-view="teach">All lessons</button></div></section>`;$('#app').focus();window.scrollTo(0,0)}
function openLesson(number,step=0){view='teach';session=null;lesson={number,step};chrome();const q=D.questions.find(q=>q.number===number);const steps=['Start with the idea','The complete answer','A concrete example'];$('#app').innerHTML=`<div class="study"><div class="row spread"><span class="tag">${label(q)} · Lesson ${q.number} / ${D.questions.length}</span><button data-view="teach">All lessons</button></div><h1>${esc(q.title)}</h1><div class="bar"><span style="width:${100*(step+1)/3}%"></span></div><section class="card lesson-copy" style="margin-top:24px"><p class="lesson-step-label">STEP ${step+1} OF 3 · ${steps[step]}</p><h2>${esc(step===1?q.q:steps[step])}</h2>${step===0?`<p class="notice"><b>Your goal:</b> ${esc(q.goal)}</p><p><button data-view="beginner">Explain the starting vocabulary</button></p>`:""}${paragraphs([q.teach,q.answer,q.example][step])}${step===2?`<div class="notice">Remember the connection: ${esc(q.correct)}</div>`:''}${sources(q)}</section><div class="actions">${step?'<button id="lesson-prev">← Back</button>':''}${step<2?'<button class="primary" id="lesson-next">Next step →</button>':`<button class="primary" id="lesson-practice">Try this topic →</button><button id="continue-learning">${esc(learningNextLabel(number))}</button><button id="lesson-complete">${progress.lessons[q.id]?'✓ Lesson completed':'Mark lesson read'}</button>`}</div>${[19,39].includes(number)?'<p><button data-view="math">Open RSA & hash lab</button></p>':''}</div>`;if($('#continue-learning'))$('#continue-learning').onclick=()=>continueLearning(number);if($('#lesson-prev'))$('#lesson-prev').onclick=()=>openLesson(number,step-1);if($('#lesson-next'))$('#lesson-next').onclick=()=>openLesson(number,step+1);if($('#lesson-complete'))$('#lesson-complete').onclick=()=>{progress.lessons[q.id]=true;save();openLesson(number,2)};if($('#lesson-practice'))$('#lesson-practice').onclick=()=>{progress.lessons[q.id]=true;save();start('practice',[q,...D.cloze.filter(c=>c.source===number),...D.checks.filter(c=>c.source===number),...D.sorts.filter(c=>c.source===number).map(x=>({...x,kind:'sort'}))],number)};$('#app').focus()}
function sectionCards(){return `<div class="grid">${D.sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(completed).length;return `<section class="card"><span class="tag">${esc(s.reading)}</span><h2>${esc(s.title)}</h2><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p>${done} / ${qs.length} lessons answered correctly${done===qs.length?' · ✓ Complete':''}</p><div class="actions"><button class="primary" data-practice-section="${s.id}">Practice this section</button></div></section>`}).join('')}</div>`}
function practiceHome(){const pool=filtered(D.questions).filter(q=>!q.uncertain),done=pool.filter(completed).length;$('#app').innerHTML=heading('Practice the study guide','Choose answers—no written responses required. Missed questions return later until you get them right.')+`<section class="focus"><div><h2>${done} of ${pool.length} lessons completed</h2><p>One correct answer fills that prompt’s completion credit. Extra practice and vocabulary are tracked separately.</p><div class="actions"><button class="primary" id="quick">Review 10</button><button id="all-guide">Practice all ${pool.length}</button><button id="sort-practice">Build security sequences</button><button id="blank-practice">Fill-in-the-blank choices</button><button id="recall-blanks">Recall blanks before revealing</button><button id="mixed-topic">Mix in terms & activities</button></div></div><div class="ring">${Math.round(100*done/pool.length)}%<small>COMPLETED</small></div></section>`+sectionCards()+`<div class="notice">The full answer after each question covers all parts of the original prompt. For smaller checks on individual details, use Apply your knowledge. Completion shows practice done, not a guarantee of exam readiness.</div>`;$('#quick').onclick=()=>{const rank=x=>{const p=progress.cards[x.id];return p?.level===0?0:!p?1:p.due<=Date.now()?2:3};start('practice',shuffle(pool).sort((a,b)=>rank(a)-rank(b)).slice(0,10))};$('#all-guide').onclick=()=>start('practice',shuffle(pool));$('#sort-practice').onclick=()=>start('practice',shuffle(filtered(D.sorts)).map(x=>({...x,kind:'sort'})));$('#recall-blanks').onclick=()=>start('flash',shuffle(filtered(D.cloze)));$('#blank-practice').onclick=()=>start('practice',shuffle(filtered(D.cloze)));$('#mixed-topic').onclick=()=>start('practice',shuffle(filtered(mixedPool())).slice(0,20))}
function mixedPool(){return [...D.questions.filter(q=>!q.uncertain),...D.checks,...D.vocab,...D.cloze,...D.sorts.map(x=>({...x,kind:'sort'})),...D.vocab.filter(x=>x.exp).map(x=>({...x,id:x.id+'-build',kind:'wordbank',q:`${["PI","AI","PO","AO"].includes(x.term)?"In the process-measurement formulas, build":"Build"} the full name of ${x.term}`}))]}
function prepare(x){if(x.kind==='cloze')return {...x,bank:shuffle([...new Set([x.correct,...x.distractors].flatMap(a=>a.split('; ')))]),picked:[]};if(x.kind==='sort')return {...x,current:shuffledOrder(x.items)};if(x.kind==='wordbank')return {...x,bank:shuffledOrder(x.exp.split(/\s+/).map((word,i)=>({word,i}))),picked:[]};return {...x,options:shuffle([x.correct,...x.distractors])}}
function start(mode,items,lessonNumber=null){if(!items.length){$('#app').innerHTML='<section class="card"><h2>No items in this selection</h2><button data-view="practice">Choose another topic</button></section>';return}session={mode,items:items.map(prepare),index:0,total:items.length,cleared:new Set(),first:{},right:0,graded:false,revealed:false,lessonNumber};renderSession();window.scrollTo(0,0)}
function preteach(x){const q=source(x);return `<details class="card"><summary>Teach me first · show the rule</summary><div class="lesson-copy">${paragraphs(x.teach)}${q?`<p><strong>Example:</strong> ${esc(x.example||q.example)}</p>`:''}</div></details>`}
function feedback(x,ok){const q=source(x);return `<div class="feedback" role="status"><strong>${ok?'✓ Correct':'Not quite — let’s make it simple'}</strong><h3>${x.kind==='sort'?'Correct order':x.kind==='wordbank'?'Full name':'Correct answer'}</h3>${paragraphs(x.kind==='sort'?x.items.join(' → '):x.kind==='wordbank'?x.exp:x.correct)}<h3>Why this fits</h3>${paragraphs(x.teach)}${q?`<h3>Picture the action</h3>${paragraphs(x.example||q.example)}<details><summary>Read the complete study-guide answer</summary>${paragraphs(q.answer)}</details>`:''}${sources(x)}</div>`}
function sessionHeader(x){const s=session;return `<div class="study"><div class="row spread"><span class="tag">${label(x)}</span><button data-view="${s.mode==='flash'?'flash':s.mode==='exam'?'exam':'practice'}">End session</button></div><p class="tiny">${s.mode==='exam'?'Exam':s.mode==='flash'?'Flashcards':'Practice'} · ${Math.min(s.index+1,s.items.length)} / ${s.items.length}${s.mode!=='exam'&&s.mode!=='flash'?` · ${s.cleared.size}/${s.total} cleared`:''}</p><div class="bar"><span style="width:${100*(s.mode==='exam'?s.index:s.cleared.size)/s.total}%"></span></div>`}
function renderSession(){const s=session;if(!s||s.index>=s.items.length){finish();return}chrome();const x=s.items[s.index];s.graded=false;s.revealed=false;if(s.mode==='flash'){renderFlash(x);return}if(x.kind==='cloze'){renderCloze(x);return}if(x.kind==='sort'){renderSort(x);return}if(x.kind==='wordbank'){renderWordBank(x);return}$('#app').innerHTML=sessionHeader(x)+`${x.format?`<p class="tiny muted">${esc(x.format==='tf'?'True / False':x.format==='fill'?'Fill-in-the-blank recognition':'Concept check')}</p>`:''}<h2 class="question">${esc(x.q)}</h2>${s.mode==='exam'?'':preteach(x)}<p class="eyebrow">CHOOSE ONE ANSWER</p><div class="choices">${x.options.map((o,i)=>`<button data-option="${i}"><b>${String.fromCharCode(65+i)}.</b><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback"></div></div>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(s.graded)return;const answer=x.options[+b.dataset.option];document.querySelectorAll('[data-option]').forEach(btn=>{btn.disabled=true;if(x.options[+btn.dataset.option]===x.correct)btn.classList.add('correct')});if(answer!==x.correct)b.classList.add('wrong');grade(x,answer===x.correct,answer)})}
function renderCloze(x){let i=0;const sentence=esc(x.q).replace(/____/g,()=>{const slot=i++;return x.picked[slot]!==undefined?'<button data-blank-slot="'+slot+'" aria-label="Remove '+esc(x.bank[x.picked[slot]])+'">'+esc(x.bank[x.picked[slot]])+'</button>':'<span class="tag">Blank '+(slot+1)+'</span>'});$('#app').innerHTML=sessionHeader(x)+`<h2>Complete the sentence</h2><p class="muted">Tap a word or phrase for each blank, from left to right. Tap a filled blank to remove it.</p><section class="card lesson-copy" aria-live="polite">${sentence}</section>${session.mode==='exam'?'':preteach(x)}<div class="actions">${x.bank.map((w,j)=>`<button data-blank-word="${j}" ${x.picked.includes(j)||x.picked.length===x.blanks.length?'disabled':''}>${esc(w)}</button>`).join('')}</div><div class="actions"><button id="check-blanks" class="primary" ${x.picked.length===x.blanks.length?'':'disabled'}>Check sentence</button><button id="clear-blanks">Start over</button></div><div id="feedback"></div></div>`;document.querySelectorAll('[data-blank-word]').forEach(b=>b.onclick=()=>{if(session.graded)return;x.picked.push(+b.dataset.blankWord);renderCloze(x)});document.querySelectorAll('[data-blank-slot]').forEach(b=>b.onclick=()=>{if(session.graded)return;x.picked.splice(+b.dataset.blankSlot,1);renderCloze(x)});$('#clear-blanks').onclick=()=>{if(session.graded)return;x.picked=[];renderCloze(x)};$('#check-blanks').onclick=()=>{if(session.graded||x.picked.length!==x.blanks.length)return;const answer=x.picked.map(j=>x.bank[j]).join('; ');document.querySelectorAll('[data-blank-word],[data-blank-slot],#check-blanks,#clear-blanks').forEach(b=>b.disabled=true);grade(x,answer===x.correct,answer)}}
function grade(x,ok,selected){const s=session;if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok,selected};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);$('#feedback').innerHTML=feedback(x,ok)+`<button class="primary" id="next">${s.index+1===s.items.length&&(ok||s.mode==='exam')?'See results':'Continue →'}</button>`;$('#next').onclick=advance}
function advance(){const s=session,x=s.items[s.index];if(!s.lastOK&&s.mode!=='exam')s.items.splice(Math.min(s.index+4,s.items.length),0,prepare(x));s.index++;renderSession();$('#app').focus()}
function finish(){const s=session;if(!s)return;const missed=Object.entries(s.first).filter(([,v])=>!v.ok).map(([id])=>s.items.find(x=>x.id===id));$('#app').innerHTML=`<div class="study"><section class="card"><div class="eyebrow">CIS 425 · SESSION COMPLETE</div><h1>${s.mode==='exam'?`${s.right} / ${s.total} on first attempts`:s.mode==='flash'?'Recall round completed':'Every item cleared ✓'}</h1><p>${s.mode==='exam'?'Your score uses your first answer to each question. Review missed topics below.':`You answered or recalled all ${s.total} items successfully, including any retries.`}</p><p>${missed.length} item${missed.length===1?'':'s'} needed another look on the first attempt.</p><div class="actions"><button class="primary" data-view="practice">Back to practice</button>${missed.length?'<button id="retry-missed">Practice missed items</button>':''}${s.lessonNumber?`<button class="primary" id="continue-learning">${esc(learningNextLabel(s.lessonNumber))}</button><button data-lesson="${s.lessonNumber}">Return to the lesson</button>`:''}</div></section>${s.mode==='exam'?missed.map(x=>`<details class="card exam-review"><summary>${esc(x.q)}</summary>${feedback(x,false)}</details>`).join(''):''}</div>`;if(s.lessonNumber&&$('#continue-learning'))$('#continue-learning').onclick=()=>continueLearning(s.lessonNumber);if($('#retry-missed'))$('#retry-missed').onclick=()=>start('practice',shuffle(missed))}
function flashHome(){$('#app').innerHTML=heading('Flip, remember, repeat','Think of the answer, then tap the card. Mark honestly: remembered cards earn completion credit, and missed cards come back.')+`<div class="grid"><section class="card"><h2>Study-guide flashcards</h2><p>${filtered(D.questions).length} lesson prompts with complete answers.</p><button class="primary" id="flash-guide">Study guide cards</button></section><section class="card"><h2>Vocabulary flashcards</h2><p>${filtered(D.vocab).length} terms, including full abbreviation names.</p><button class="primary" id="flash-vocab">Study terms</button></section></div>`;$('#flash-guide').onclick=()=>start('flash',shuffle(filtered(D.questions)));$('#flash-vocab').onclick=()=>start('flash',shuffle(filtered(D.vocab)))}
function renderFlash(x){const s=session;$('#app').innerHTML=sessionHeader(x)+`<p class="eyebrow" id="flash-side">FRONT · TAP TO REVEAL</p><button class="card flashcard" id="flip" aria-label="Reveal answer"><h2>${esc(x.term||x.q)}</h2></button><div id="rating"></div></div>`;$('#flip').onclick=()=>{s.revealed=!s.revealed;$('#flash-side').textContent=s.revealed?'BACK · TAP TO HIDE':'FRONT · TAP TO REVEAL';$('#flip').setAttribute('aria-label',s.revealed?'Hide answer':'Reveal answer');$('#flip').innerHTML=s.revealed?`${x.exp?`<h2>${esc(x.exp)}</h2>`:''}${paragraphs(x.answer)}`:`<h2>${esc(x.term||x.q)}</h2>`;$('#rating').innerHTML=s.revealed?`<div class="actions"><button id="forgot">Still learning · show again</button><button class="primary" id="remembered">I remembered it</button></div><details><summary>Help me understand</summary>${paragraphs(x.teach)}</details>`:'';if(s.revealed){$('#forgot').onclick=()=>rate(false);$('#remembered').onclick=()=>rate(true)}};function rate(ok){if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);advance()}}
function applyHome(){$('#app').innerHTML=heading('Apply your knowledge','Extra checks on the same guide topics, kept separate from the lesson prompts.')+`<section class="card"><h2>${filtered(D.checks).length} focused checks</h2><p>Recognize examples, distinguish similar terms, and test individual parts of multi-part guide questions.</p><button class="primary" id="apply-start">Practice these checks</button><button id="cloze-start">Fill-in-the-blank choices</button></section>`;$('#apply-start').onclick=()=>start('practice',shuffle(filtered(D.checks)));$('#cloze-start').onclick=()=>start('practice',shuffle(filtered(D.cloze)))}
function sortHome(){$('#app').innerHTML=heading('Put the steps in order','Every attempt starts shuffled. Conceptual workflows for the same midterm topics. These teach the reasoning rather than tool commands.')+`<div class="grid">${filtered(D.sorts).map(x=>`<section class="card"><h2>${esc(x.q)}</h2><p>${label(x)}</p><button class="primary" data-sort="${x.id}">Build this sequence</button></section>`).join('')}</div>${filtered(D.sorts).length?'':'<p>No sequence activities in this section. Select All topics to see them.</p>'}`}
function renderSort(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2>${preteach(x)}<div class="order">${x.current.map((v,i)=>`<div><b>${i+1}</b><span>${esc(v)}</span><button data-move="${i}" data-delta="-1" aria-label="Move ${esc(v)} up" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-delta="1" aria-label="Move ${esc(v)} down" ${i===x.current.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="primary" id="check-order">Check order</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.delta);[x.current[i],x.current[j]]=[x.current[j],x.current[i]];renderSort(x)});$('#check-order').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-move],#check-order').forEach(b=>b.disabled=true);grade(x,x.current.every((v,i)=>v===x.items[i]))}}
function abbrevHome(){const items=filtered(D.vocab).filter(v=>v.exp);$('#app').innerHTML=heading('Abbreviations, fully understood','Choose the name or build it one word at a time. Then connect it to what it actually means.')+`<section class="card"><h2>${items.length} abbreviations</h2><p>${items.map(v=>esc(v.term)).join(' · ')}</p><div class="actions"><button class="primary" id="abbrev-choice">Choose the full name</button><button id="abbrev-build">Build with a word bank</button></div></section>`;$('#abbrev-choice').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-name',q:`${["PI","AI","PO","AO"].includes(v.term)?"In the process-measurement formulas":"In this CIS 425 course"}, what does ${v.term} stand for?`,correct:v.exp,distractors:D.abbreviationDistractors[v.term]}))));$('#abbrev-build').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-build',kind:'wordbank',q:`${["PI","AI","PO","AO"].includes(v.term)?"In the process-measurement formulas, build":"Build"} the full name of ${v.term}`}))))}
function renderWordBank(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2><p>Tap words in order. Tap a selected word to return it to the bank.</p><div class="word-answer"><div class="wordbank">${x.picked.map((v,i)=>`<button data-remove="${i}">${esc(v.word)} ×</button>`).join('')||'<span class="muted">Your answer will appear here</span>'}</div></div><div class="wordbank">${x.bank.map(v=>`<button data-word="${v.i}" ${x.picked.some(w=>w.i===v.i)?'disabled':''}>${esc(v.word)}</button>`).join('')}</div><button class="primary" id="check-bank" ${x.picked.length!==x.bank.length?'disabled':''}>Check name</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{x.picked.push(x.bank.find(w=>w.i===+b.dataset.word));renderWordBank(x)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{x.picked.splice(+b.dataset.remove,1);renderWordBank(x)});$('#check-bank').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-word],[data-remove],#check-bank').forEach(b=>b.disabled=true);grade(x,x.picked.map(v=>v.word).join(' ')===x.exp)}}
function termsHome(){$('#app').innerHTML=heading('Words you can actually understand','Definitions are tied to the same guide topics. Open the related lesson for context.')+`<label class="search-label">Find a term<input type="search" id="search" placeholder="Try: TCP, signature, IDS…"></label><div class="wordlist" id="terms"></div>`;function update(){const str=$('#search').value.toLowerCase(),vs=filtered(D.vocab).filter(v=>(v.term+' '+v.exp+' '+v.answer).toLowerCase().includes(str));$('#terms').innerHTML=vs.map(v=>`<article><span class="tag">${label(v)}</span><h3>${esc(v.term)}${v.exp?' · '+esc(v.exp):''}</h3>${paragraphs(v.answer)}${paragraphs(v.teach)}<button data-lesson="${v.source}">See it in context</button></article>`).join('')||'<p>No matching terms.</p>'}$('#search').oninput=update;update()}
function guideHome(){$('#app').innerHTML=heading('The answered midterm guide','Professor samples and supporting lessons, with complete answers, examples, and source labels.')+`<div class="notice">${filtered(D.questions).length} of ${D.questions.length} lessons shown. Lessons 1–21 answer every professor sample in order. Four disputed or imprecise samples are explained but excluded from scored exams. Open Sources & corrections for the cross-check record.</div><div class="lesson-list">${filtered(D.questions).map(q=>`<article class="card"><span class="tag">${label(q)} · Guide ${q.number}</span><h3>${esc(q.title)}</h3><details><summary>${esc(q.q)}</summary><div class="lesson-copy">${q.originalPrompt?`<p class="source-note">Original guide wording: ${esc(q.originalPrompt)}</p>`:''}${paragraphs(q.answer)}<h3>Let’s make it simple</h3>${paragraphs(q.teach)}<h3>Example</h3>${paragraphs(q.example)}</div>${sources(q)}<div class="actions"><button data-lesson="${q.number}">Teach me step by step</button><button data-question="${q.number}">Practice this prompt</button></div></details></article>`).join('')}</div>`}
function readingsHome(){$('#app').innerHTML=heading('Every source, with corrections','How the supplied material shapes the midterm section.')+`<div class="notice">All ${D.sources.length} source records are accounted for, including the original 11 references and all eight lecture decks. The single-page CIS 425 - 827.pdf is the replacement you approved for the missing annotated file. The textbook was indexed across 786 PDF pages, with study scope limited to assigned chapters and guide-relevant definitions. Original textbook pages, private submissions, and lab attack instructions are not republished. All eight lecture decks are now reviewed directly. Lectures 2–4 were recovered from PPTs_export.zip, and the duplicate Lecture 3 export has matching slide/note text. The original annotated exercise is now available too and matches the replacement text. Use Topic checklist for source-to-lesson links.</div><section class="card"><h2>Exam scope and estimates</h2><p>Professor guide: 15 T/F, 20 multiple choice, 10 blanks, 5–7 discussions. October 15 notes give ranges: 10–15 T/F, 20–25 MC, 10–12 blanks, 5–7 discussions. Counts are estimates.</p><p>Prioritize explanations, technology choices, business impact, and defenses. Career recruiting lists and unrelated textbook chapters stay outside practice.</p></section><h2>Source coverage</h2>${D.sources.map(x=>`<details class="card"><summary>${x.id}. ${esc(x.name)}</summary><p>${esc(D.sourceUses[x.id])}</p><p class="tiny">${x.units} extracted page/slide/note units · ${x.chars.toLocaleString()} text characters${x.note?' · '+esc(x.note):''}</p></details>`).join('')}<h2>Cross-check of the second guide and class materials</h2>${D.corrections.map(([status,title,text])=>`<article class="card"><span class="tag">${esc(status)}</span><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}<section class="card"><h2>Primary clarification references</h2><p>The supplied course material sets scope. These references clarify technical terminology. Linked videos are not represented as watched or transcribed.</p><ul>${D.references.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a></li>`).join('')}</ul></section>`}
function readingLink(r){return `<li><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a></li>`}
function examHome(){$('#app').innerHTML=heading('Practice the exam format','First answers count. These are authored practice questions, not predicted exam questions.')+`<section class="card"><h2>Midterm rehearsal</h2><p>15 true/false + 20 multiple choice + 10 fill-in-the-blank choices. Then choose 5 or 7 discussion prompts using the separate rubric. Discussion ratings are self-assessment and never added to your objective score.</p><p>Four uncertain professor samples stay in the answered guide but outside scored exams. Some repeated concepts are intentional; a practice score measures this bank, not your entire exam readiness.</p><div class="actions"><button class="primary" id="mock-exam">Start 45-question rehearsal</button><button id="topic-exam">20 questions from selected topic</button><button data-view="discussion">Discussion rehearsal</button></div></section>`;$('#mock-exam').onclick=()=>{section=0;start('exam',buildMidtermItems())};$('#topic-exam').onclick=()=>{const pool=filtered([...D.questions.filter(q=>!q.uncertain&&!['tf','fill','discussion'].includes(q.format)),...D.trueFalse,...D.cloze]);start('exam',shuffle(pool).slice(0,20))}}
const mapViews={
defense:{title:'From attack to business response',intro:'Select each stage to connect the labs with security decisions.',parts:[['Trust abuse','A believable request','Phishing and SET abuse trust. Teach verification, filter messages, and use phishing-resistant authentication.',31],['Endpoint access','A process acts on a host','Malware and keyloggers can capture data before encryption. Use least privilege, patching, application controls, and EDR.',32],['Outbound control','A reverse connection','A compromised host may connect outward. Monitor process-to-network activity and apply appropriate egress restrictions.',4],['Business response','Contain and recover','Correlate events, preserve evidence, identify affected accounts and systems, and follow containment and recovery procedures.',34]]},
keys:{title:'Whose key does what?',intro:'For confidentiality think recipient. For signatures think sender. A public key still needs a trusted identity binding.',parts:[['Encrypt for Bob','Bob’s public key','Alice protects the message so Bob can recover it using Bob’s private key.',38],['Decrypt as Bob','Bob’s private key','Bob keeps this secret. Someone holding only the public key should not be able to recover properly encrypted content.',38],['Sign as Alice','Alice’s private signing key','Alice authorizes the message. The signature does not by itself hide the message.',18],['Verify Alice','Alice’s public verification key','Bob checks the signature using a key he trusts to belong to Alice. A plain hash alone cannot establish that identity.',37]]},
chain:{title:'Bitcoin uses several mechanisms',intro:'These mechanisms solve different problems and must work together.',parts:[['Hash','Commit to data','A digest changes when data changes. SHA-256 contributes to Bitcoin hashing and proof of work.',19],['Signature','Authorize spending','The spender proves authorization under an output’s conditions using a private key, without disclosing that key.',21],['Consensus','Agree on history','Nodes validate rules and follow the valid chain with greatest cumulative proof of work.',20],['Incentive','Reward participation','Block subsidy and transaction fees motivate miners. Incentives do not eliminate all attacks or business risks.',41]]}
};
function mapHome(selected='defense'){const m=mapViews[selected];$('#app').innerHTML=heading('See the connections','Follow the security goal, evidence, and defense.')+`<div class="actions">${Object.entries(mapViews).map(([k,v])=>`<button data-map="${k}" aria-pressed="${k===selected}">${esc(v.title)}</button>`).join('')}</div><section class="card" style="margin-top:20px"><h2>${esc(m.title)}</h2><p>${esc(m.intro)}</p><div class="map-stack">${m.parts.map((p,i)=>`<button data-map-part="${i}" aria-pressed="${i===0}"><b>${esc(p[0])}</b> · ${esc(p[1])}</button>`).join('')}</div><div class="notice" id="map-detail" aria-live="polite"></div></section>`;function detail(i){const p=m.parts[i];$('#map-detail').innerHTML=`<h3>${esc(p[0])}</h3>${paragraphs(p[2])}<button data-lesson="${p[3]}">Review the lesson</button>`;document.querySelectorAll('[data-map-part]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.mapPart===i)))}document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>mapHome(b.dataset.map));document.querySelectorAll('[data-map-part]').forEach(b=>b.onclick=()=>detail(+b.dataset.mapPart));detail(0)}

function modPow(base,exp,mod){let b=BigInt(base),e=BigInt(exp),m=BigInt(mod),r=1n;while(e>0n){if(e&1n)r=r*b%m;b=b*b%m;e>>=1n}return Number(r)}
const rsaCases=[{p:5,q:11,e:3,d:27,m:7},{p:3,q:11,e:3,d:7,m:4},{p:7,q:11,e:7,d:43,m:9}];
let rsaCase=0;
function rsaResult(c){const n=c.p*c.q,phi=(c.p-1)*(c.q-1),cipher=modPow(c.m,c.e,n);return {n,phi,cipher,plain:modPow(cipher,c.d,n)}}
function mathHome(){const c=rsaCases[rsaCase],r=rsaResult(c);$('#app').innerHTML=heading('RSA & hash lab','Work through the classroom arithmetic, then compare real SHA-256 digests.')+`<section class="card"><h2>Small RSA example</h2><p>Teaching numbers only. This is unpadded textbook RSA, unsuitable for real secrets.</p><div class="formula-grid"><div>Primes<strong>${c.p} and ${c.q}</strong></div><div>Message<strong>${c.m}</strong></div></div><div id="rsa-work"></div><div class="actions"><button class="primary" id="rsa-step">Reveal next step</button><button id="rsa-new">Different example</button><button data-lesson="39">Explain the rule</button></div></section><section class="card" style="margin-top:22px"><h2>A one-character change, a new digest</h2><p>SHA-256 always produces 256 bits, shown as 64 hexadecimal characters. Hashing is not encryption. This comparison does not prove that collisions are impossible.</p><label>Message A<input type="text" id="hash-a" value="Pay Bob 10" maxlength="300"></label><label>Message B<input type="text" id="hash-b" value="Pay Bob 11" maxlength="300"></label><button id="hash-run" class="primary">Compare SHA-256 digests</button><div id="hash-output" aria-live="polite" style="overflow-wrap:anywhere"></div></section>`;const steps=[`n = p × q = ${c.p} × ${c.q} = ${r.n}.`,`φ(n) = (p − 1)(q − 1) = ${r.phi}. Choose e = ${c.e}, coprime to φ(n).`,`d = ${c.d}: e × d = ${c.e*c.d}, leaving remainder 1 modulo ${r.phi}. Public key: (${r.n}, ${c.e}); private exponent: ${c.d}.`,`Encrypt: ${c.m}^${c.e} mod ${r.n} = ${r.cipher}.`,`Decrypt: ${r.cipher}^${c.d} mod ${r.n} = ${r.plain}. The original message is recovered.`];let step=0;$('#rsa-step').onclick=()=>{if(step>=steps.length)return;$('#rsa-work').insertAdjacentHTML('beforeend',`<p class="formula-step">${esc(steps[step++])}</p>`);$('#rsa-step').disabled=step===steps.length};$('#rsa-new').onclick=()=>{rsaCase=(rsaCase+1)%rsaCases.length;mathHome()};$('#hash-run').onclick=async()=>{const output=$('#hash-output'),a=$('#hash-a').value,b=$('#hash-b').value;try{if(!globalThis.crypto?.subtle)throw Error('SHA-256 requires HTTPS or localhost in this browser.');const digest=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(x=>x.toString(16).padStart(2,'0')).join('');const [ha,hb]=await Promise.all([digest(a),digest(b)]);output.innerHTML=`<p><b>A</b> ${ha}</p><p><b>B</b> ${hb}</p><p>${ha===hb?'Digests match for these inputs.':'Digests differ. The content comparison detects this change.'} A trusted reference or authenticated construction is needed to defend against malicious replacement.</p>`}catch(e){output.textContent=e.message}}}

function beginnerHome(){$('#app').innerHTML=heading('Start from zero','Build the vocabulary first, then follow one connected route through the midterm.')+`<section class="card"><h2>One story to keep in mind</h2><p>A business stores information on computers. People and programs use that information. Networks let the computers exchange it. An attacker may trick a person, exploit a weakness, or misuse authorized access. Defenders try to prevent the action, observe evidence, limit damage, and recover.</p><p>You do not need to know the lab commands to begin. For each topic, learn what it does, why the business needs it, how it can fail, and which evidence or defense fits.</p><h3>Words used throughout these lessons</h3><dl>${D.primer.map(x=>`<dt><b>${esc(x.term)}</b></dt><dd>${esc(x.meaning)}</dd>`).join('')}</dl></section><section class="card" style="margin-top:20px"><h2>A beginner route</h2><p>Work down the list. Each lesson has a plain explanation, full answer, concrete example, and practice. Marking a lesson read is different from demonstrating recall.</p><div class="lesson-list">${D.beginnerRoute.map(n=>{const q=D.questions.find(q=>q.number===n);return `<button data-lesson="${n}"><span class="badge">${n}</span><span class="lesson-label">${esc(q.title)}<small>${esc(q.goal)}</small></span></button>`}).join('')}</div></section><div class="actions"><button data-view="samples">See every professor example</button><button data-view="coverage">Check topic coverage</button></div>`}

function samplesHome(){$('#app').innerHTML=heading('The professor’s 21 examples','Original question types and multiple-choice option order, with study answers and explanations.')+`<div class="notice">These examples illustrate the exam’s scope; they are not the whole question bank. All six discussion prompts have model answers. Four examples contain wording that needs qualification; each gives the likely classroom selection where supported and explains the uncertainty.</div>`+['True/False','Multiple choice','Fill in the blank','Discussion'].map(type=>`<section style="margin-top:28px"><h2>${esc(type)}</h2>${D.samples.filter(x=>x.type===type).map(x=>{const q=D.questions.find(q=>q.number===x.source);return `<article class="card" style="margin-top:16px"><span class="tag">${esc(x.label)}${x.uncertain?' · wording needs qualification':''}</span><h3>${esc(x.prompt)}</h3>${x.options.length?`<ol type="A">${x.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>`:''}<details><summary>Reveal answer and reasoning</summary><p><b>${esc(x.shortAnswer)}</b></p>${paragraphs(q.answer)}${q.rubric?'<h3>A complete response includes</h3><ul>'+q.rubric.map(r=>'<li>'+esc(r)+'</li>').join('')+'</ul>':''}${sources(q)}<button data-lesson="${x.source}">Learn this step by step</button></details></article>`}).join('')}</section>`).join('')}

function coveragePool(entry){const numbers=new Set(entry.topics.flatMap(t=>t[1]));return [...D.questions.filter(q=>numbers.has(q.number)&&!q.uncertain),...D.checks.filter(q=>numbers.has(q.source)),...D.vocab.filter(q=>numbers.has(q.source)),...D.cloze.filter(q=>numbers.has(q.source))]}
function coverageHome(){$('#app').innerHTML=heading('What each source teaches','A topic checklist tied to lessons and practice, with direct lecture and textbook coverage.')+`<div class="notice">Covered means the content and practice are present. A correct practice answer is evidence from that item, not proof of complete understanding. Review the examples, try unfamiliar scenarios, and rehearse discussions without looking at the model. The original 11 references and all 8 lecture decks have been reviewed. Videos linked inside them are not claimed as watched or transcribed.</div>${D.coverage.map(entry=>{const pool=coveragePool(entry),done=pool.filter(completed).length;return `<section class="card" style="margin-top:22px"><h2>${esc(entry.title)}</h2><p class="source-note">${esc(entry.basis)}</p><p>${done} / ${pool.length} linked practice items answered correctly at least once</p><div class="bar"><span style="width:${pool.length?100*done/pool.length:0}%"></span></div>${entry.topics.map(([title,nums])=>`<details><summary>${esc(title)}</summary><div class="actions">${nums.map(n=>`<button data-lesson="${n}">${esc(D.questions.find(q=>q.number===n).title)}</button>`).join('')}</div></details>`).join('')}<button class="primary" data-coverage="${esc(entry.id)}">Practice this source’s topics</button></section>`}).join('')}`;document.querySelectorAll('[data-coverage]').forEach(b=>b.onclick=()=>{section=0;start('practice',shuffle(coveragePool(D.coverage.find(x=>x.id===b.dataset.coverage))))})}

let discussionLimit=0;
function buildMidtermItems(){const mc=[],used=new Set(),candidates=shuffle([...D.questions,...D.checks].filter(q=>!q.uncertain&&!['tf','fill','discussion'].includes(q.format)));function take(section){const q=candidates.find(q=>(!section||q.section===section)&&!used.has(q.number||q.source));if(q){mc.push(q);used.add(q.number||q.source)}}for(const section of D.sections)for(let i=0;i<2;i++)take(section.id);while(mc.length<20){const before=mc.length;take(0);if(mc.length===before)break}return [...shuffle(D.trueFalse).slice(0,15),...shuffle(mc),...shuffle(D.cloze).slice(0,10)]}
function discussionHome(){const pool=D.discussions.filter(q=>!section||q.section===section),qs=discussionLimit?shuffle(pool).slice(0,discussionLimit):pool;$('#app').innerHTML=heading('Explain it before revealing it','Rehearse out loud or on paper. Then compare your reasoning with the model and rubric.')+`<div class="notice">Self-assessment only: the app does not automatically grade written or spoken answers. Define the concept, explain the mechanism, apply it to a business, and mention a limitation. The six professor examples and one added lab/business scenario form this discussion bank.</div><div class="actions"><button id="discussion-five">Rehearse 5 from all topics</button><button id="discussion-seven">Rehearse all 7</button></div>${qs.map(q=>`<section class="card" style="margin-top:20px"><span class="tag">${esc(q.sample||'Added lab/business scenario')}</span><h2>${esc(q.q)}</h2><p>Try a 2–3 minute explanation before opening the model.</p><details><summary>Reveal model answer and checklist</summary>${paragraphs(q.answer)}<h3>Check your coverage</h3>${q.rubric.map((r,i)=>`<label style="display:block;padding:10px"><input type="checkbox" data-rubric="${q.id}-${i}" ${progress.rubrics?.[q.id+'-'+i]?'checked':''}> ${esc(r)}</label>`).join('')}<p class="tiny">A check records your judgment; it does not verify correctness.</p>${sources(q)}<button data-lesson="${q.number}">Review this lesson</button></details></section>`).join('')}`;document.querySelectorAll('[data-rubric]').forEach(b=>b.onchange=()=>{progress.rubrics??={};progress.rubrics[b.dataset.rubric]=b.checked;save()});$('#discussion-five').onclick=()=>{section=0;discussionLimit=5;discussionHome()};$('#discussion-seven').onclick=()=>{section=0;discussionLimit=7;discussionHome()}}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view)navigate(b.dataset.view);else if(b.dataset.lesson)openLesson(+b.dataset.lesson);else if(b.dataset.practiceSection){section=+b.dataset.practiceSection;view='practice';start('practice',shuffle(filtered(D.questions)))}else if(b.dataset.question)start('practice',[D.questions.find(q=>q.number===+b.dataset.question)]);else if(b.dataset.sort)start('practice',[{...D.sorts.find(x=>x.id===b.dataset.sort),kind:'sort'}])});
fetch('cis425-content.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Could not load study content');return r.json()}).then(data=>{D=data;render()}).catch(()=>{$('#app').innerHTML='<section class="card"><h1>Study content could not load</h1><p>Refresh the page to try again. CIS 425 needs cis425-content.json alongside this page.</p><button onclick="location.reload()">Try again</button></section>'});

